const COPY = { en: EN, "zh-Hans": ZH, es: ES, "pt-BR": PT, tr: TR, vi: VI, id: ID, ja: JA, ko: KO };
export const intelToolsCopyLocales = () => Object.keys(COPY);
/** Copy for a locale; non-index locales get English (their pages are noindex). */
export const intelToolsCopy = (locale) => COPY[locale] || EN;
export const isIntelToolIndexLocale = (locale) => INTEL_TOOL_INDEX_LOCALES.includes(locale);
